# /etc/nginx/conf.d/app.example.com.conf
upstream app_backend {
    server 10.20.0.15:8080;             # private address, not reachable from the internet
    keepalive 16;
}

server {
    listen 443 ssl;
    http2 on;
    server_name app.example.com;
    ssl_certificate     /etc/nginx/ssl/app.example.com.fullchain.pem;
    ssl_certificate_key /etc/nginx/ssl/app.example.com.key;

    client_max_body_size 5m;
    proxy_connect_timeout 5s;
    proxy_read_timeout    30s;
    proxy_send_timeout    30s;

    # Block internal paths that must never be public
    location ^~ /internal/ { return 404; }
    location ~ /\.        { return 404; }

    location / {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $remote_addr;   # overwrite, do not append client input
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_hide_header X-Powered-By;
    }
}

